--- webapp/dashboard/AnnouncementBanner.tsx ---
```tsx
import React, { useCallback, useEffect, useState } from 'react';
import NotificationStrip from '../NotificationStrip';
import { useDashboardConfig } from './useDashboardConfig';
import userPrefs from '../lib/userPrefs';

type ActiveBanner = {
  campaignId: string;
  title?: string;
  message?: string;
};

function useAnnouncementDismissal(campaignId?: string) {
  const key = campaignId ? `dashboardBannerDismissed:${campaignId}` : null;
  const [dismissed, setDismissed] = useState<boolean>(() => {
    if (!key) return false;
    try {
      return !!userPrefs.get(key);
    } catch {
      return false;
    }
  });

  useEffect(() => {
    if (!key) return;
    try {
      const val = userPrefs.get(key);
      setDismissed(!!val);
    } catch {
      // keep silent on prefs read errors to preserve current behavior
      setDismissed(false);
    }
  }, [key]);

  const dismiss = useCallback(() => {
    if (!key) return;
    try {
      userPrefs.set(key, true);
    } catch {
      // swallow prefs write errors
    }
    setDismissed(true);
  }, [key]);

  return { dismissed, dismiss };
}

export default function AnnouncementBanner(): JSX.Element | null {
  // useDashboardConfig returns { activeBanner } in the current codebase tests
  const { activeBanner } = useDashboardConfig() as { activeBanner?: ActiveBanner } | any;
  if (!activeBanner || !activeBanner.campaignId) return null;

  const { campaignId, title, message } = activeBanner;
  const { dismissed, dismiss } = useAnnouncementDismissal(campaignId);

  if (dismissed) return null;

  // Render using existing NotificationStrip; onClose should hide and persist
  return (
    <NotificationStrip title={title} onClose={dismiss}>
      {message}
    </NotificationStrip>
  );
}
```

--- webapp/dashboard/__tests__/AnnouncementBanner.test.tsx ---
```tsx
import React from 'react';
import { render, screen, fireEvent, cleanup } from '@testing-library/react';
import AnnouncementBanner from '../AnnouncementBanner';

// Mock useDashboardConfig the way other dashboard tests do
jest.mock('../useDashboardConfig', () => {
  return {
    __esModule: true,
    useDashboardConfig: jest.fn(),
  };
});
const { useDashboardConfig } = require('../useDashboardConfig') as { useDashboardConfig: jest.Mock };

// Mock userPrefs (the component imports ../lib/userPrefs relative to dashboard; from tests this is ../../lib/userPrefs)
jest.mock('../../lib/userPrefs', () => {
  return {
    __esModule: true,
    // we'll override get/set in tests via the exported spies below
    get: jest.fn(),
    set: jest.fn(),
  };
});
const userPrefs = require('../../lib/userPrefs') as { get: jest.Mock; set: jest.Mock };

// Mock NotificationStrip to expose a predictable "Close" button for testing
jest.mock('../NotificationStrip', () => {
  const React = require('react');
  return {
    __esModule: true,
    default: ({ title, children, onClose }: any) =>
      React.createElement(
        'div',
        { 'data-testid': 'mock-notification-strip' },
        React.createElement('div', null, title),
        React.createElement('button', { onClick: onClose, 'aria-label': 'close-banner' }, 'Close'),
        React.createElement('div', null, children)
      ),
  };
});

afterEach(() => {
  jest.resetAllMocks();
  cleanup();
});

test('AnnouncementBanner dismissal behavior first visit: banner visible; clicking close hides it and persists preference', () => {
  // Setup: active banner present
  useDashboardConfig.mockReturnValue({
    activeBanner: { campaignId: 'camp1', title: 'Hello', message: 'Welcome message' },
  });

  // Initially no persisted dismissal
  userPrefs.get.mockImplementation((key: string) => undefined);
  userPrefs.set.mockImplementation(() => {});

  render(<AnnouncementBanner />);

  // Banner should show
  expect(screen.getByTestId('mock-notification-strip')).toBeInTheDocument();
  expect(screen.getByText('Hello')).toBeInTheDocument();

  // Click the Close button
  const closeButton = screen.getByRole('button', { name: /close-banner/i });
  fireEvent.click(closeButton);

  // Banner should disappear immediately
  expect(screen.queryByTestId('mock-notification-strip')).not.toBeInTheDocument();

  // Preference should have been persisted for this campaign
  expect(userPrefs.set).toHaveBeenCalledWith('dashboardBannerDismissed:camp1', true);
});

test('AnnouncementBanner stays hidden on refresh when dismissed for the same campaignId', () => {
  // Simulate persisted dismissal present
  useDashboardConfig.mockReturnValue({
    activeBanner: { campaignId: 'camp1', title: 'Hello', message: 'Welcome message' },
  });

  userPrefs.get.mockImplementation((key: string) => {
    if (key === 'dashboardBannerDismissed:camp1') return true;
    return undefined;
  });

  render(<AnnouncementBanner />);

  // Banner should not render when pref says dismissed
  expect(screen.queryByTestId('mock-notification-strip')).not.toBeInTheDocument();
});

test('AnnouncementBanner shows again for a different campaignId even if old one was dismissed', () => {
  // First, the hook returns a NEW campaign id
  useDashboardConfig.mockReturnValue({
    activeBanner: { campaignId: 'camp2', title: 'New Campaign', message: 'New message' },
  });

  // The user had dismissed camp1 but not camp2
  userPrefs.get.mockImplementation((key: string) => {
    if (key === 'dashboardBannerDismissed:camp1') return true;
    if (key === 'dashboardBannerDismissed:camp2') return undefined;
    return undefined;
  });

  render(<AnnouncementBanner />);

  // Banner for camp2 should render
  expect(screen.getByTestId('mock-notification-strip')).toBeInTheDocument();
  expect(screen.getByText('New Campaign')).toBeInTheDocument();
});
